# Once output starts flowing, a short idle gap means the program has
# (for now) stopped producing output, so we can return promptly.  The
# ``timeout`` (wait_sec) bounds how long we keep *waiting for output to
# appear or resume* -- e.g. across a mid-command ``sleep`` -- so delayed
# output is still captured without burning the full window every call.
idle_window = 0.10
deadline = time.monotonic() + max(timeout, 0.0)
if initial:
    deadline = max(deadline, time.monotonic() + 0.5)

while True:
    remaining = deadline - time.monotonic()
    # Wait for the next data: at least the idle window, but up to the
    # remaining grace time so output that has not yet appeared (a slow
    # or blocked command) is still awaited.
    wait = idle_window if remaining < idle_window else remaining
    try:
        rlist, _, _ = select.select([self._master_fd], [], [], wait)
    except (OSError, ValueError):
        break
    if rlist:
        try:
            chunk = os.read(self._master_fd, 65536)
        except OSError:
            break
        if not chunk:
            break
        self._stream.feed(chunk)
        # Data arrived; drain any immediately-available follow-on bytes
        # using only the short idle window.  If the stream stays idle
        # for a full idle_window, the program has paused and we return.
        while True:
            try:
